WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (412::BIGINT, 'Califica duro pero de forma justificada, cada punto que rebaja tiene una razón clara. Es súper amable y está dispuesto a ayudar. Da de las mejores retroalimentaciones que he visto. Muchos papers. Totalmente recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'b9109a3b0cdf8783fffcb8c3b3e5ed23ad702b48b11e4684fcdd1f46a90aef37'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, '5ee0c53a4693e87bc050b9567e999b9edb6bc08b1edc44297b06cfa7334a01b4'::TEXT, ARRAY[3056, 3052, 1321]::BIGINT[]),
    (412::BIGINT, 'Buen profe, toma en cuenta el esfuerzo puesto por el estudiante. Da explicación y retroalimentación claras. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '65fd909648699f68135524a1d04a7d939ef44fadd15849731fe208db198e76ff'::TEXT, ARRAY[3052]::BIGINT[]),
    (412::BIGINT, 'Parece que la agarra con algunos estudiantes. Fuera de eso el curso es pesado con todos los informes, pero si uno resuelve los labs bien entonces es facil ganar buenas notas. Tiende a ser flexible con el tiempo de entregas de los lab'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'f1fa7643068541d26759b8b3839e369d46434ea2db8110b556f4f2bd634842fe'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Un poco argollero con las mujeres, pero si es hombre........., habla feo de otros profesores, dice que es el mejor de control automático, serrucha a colegas, mejor evitelo. No recomendado.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-07-01T00:00:00+00:00'::TIMESTAMPTZ, '9b1aaf9b2900ed086b6f582382b433a008d2e30aa446224a79f94bb657974a8a'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Es pura vida, sin embargo es algo estricto para calificar, si se puede pasar bien, nada más hacer los informes con los cambios que el le va retroalimentando y dedicarle tiempo al diseño de los controles, que si se lleva bastante aveces, pero en general se aprende bastante del curso'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '30e72664a58bcc120910f8931af57e07a41d368f2767b2b846de95e1d3ae5389'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Es cierto que hace ver el curso más pesado de lo que debería, dónde algunas instrucciones son confusas, poco claras y y algunas rúbricas inconclusas o inexistentes, que después va bajando puntos. Es un curso muy interesante, pero muy pesado llevarlo con este profe,ya que siempre hay que hacer papers'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'ee532d284be57ad581530936972a49992f06c27551e24671f1492023bec76332'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Medio argollero, habla mal de los profesores, dice que es uno de los dos mejores del país en control automático, pide ayuda con la calificación del profesor para su interinato en el puesto, la agarra con algunos estudiantes intimidando. Si puede evitarlo mejor, es muy político.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '44c251e5385fc71f2b87d6e45bb1ecb999ce9a1478adbbbbf5f7f20c7f0bcef4'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Es un buen profe, ayuda mucho en clase y sobretodo en cosulta, si puede ir a consulta hagalo que el lo toma en cuenta. El proyecto lleva tiempo y compre mucho de todo porque se les va a quemar cosas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd35f90a41d971c30dfce563b753d007242e1a7169294cd008326f2d5ca79fcaa'::TEXT, ARRAY[3052]::BIGINT[]),
    (412::BIGINT, 'El profe, en general, es pura vida y ayuda bastante mientras se hacen los experimentos. A veces puede ser medio argollero y ayudarle más a la gente que le cae bien. El profe hace entrevista aleatoria al inicio de cada clase. El lab no es difícil, tenga cuidado con el proyecto final, dedíquele tiempo'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'c9d75bfc43b79b344b00022711c4a05c729e6c3a470fc7aa021e026fa2cc25d3'::TEXT, ARRAY[3052]::BIGINT[]),
    (412::BIGINT, 'El profe como persona pura vida, pero es extremadamente confuso y desordenado, a veces deja tareas que ni él entiende cómo resolver, en los informes califica bastante duro. Es un curso que a veces requiero mucho más tiempo de lo que se le debería dedicar. Si está Interiano, matricule con Interiano.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'd7dbe02bdd03abbbc4ea107169ac07d3ec806f53fe145676ab5e9af3c7738846'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'En general el profe explica bien, pero sí deja muchos trabajos a lo largo del semestre, y es muy estricto calificando. El curso se sintió más pesado que los 2 créditos que vale. No sé si lo que alegan de acoso es cierto, pero sí se nota un favoritismo hacia las mujeres.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-06-09T00:00:00+00:00'::TIMESTAMPTZ, '3c58ebadbe1c9a3459198dcdc92f8a3f3013db4cd3b34064601721be777de2f9'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Es buena opción si se desea aprender sobre el diseño de control, brinda bastante apoyo, se exponen los proyectos y se redactan informes en inglés (opcional)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'cb1e5cb34e78f23ce851b76ab8257e227e69cd6f380774026d3ca4b86c24644b'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Es grosero, se enreda con los temas. Habla mal de los profesores, dice que es el mejor de control automático. Habla mucho de su interinato en Tec. Copia los trabajos de otros profesores. Es mejor evitarlo o esperar llevarlo con otro profesor. No se aprende mucho'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, '9c094cef460a6acc760456dda2799f48682baaca651bf9557eea6fba0fdcfc8f'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'El profe es buena gente, es comprensivo y ayuda si se lo piden. Sin embargo, a veces tiende a ser grosero y las ayudas son cortas y poco claras.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'f4a7179f8f2a59e1237ed738b5b782a2995de6f996bed4acf6299af0be730278'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Es bastate estricto para evaluar pero ayuda mucho a mejorar. Hay que hacer un informe y una presentación por proyecto, pero no siempre tca exponer. La retroalimentación es muy buena. Califica justo. La asistencia es súper importante. Todo el semstre se trabaja en tríos y se califica a los compañeros'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, '6dded3428670351513131295ff7476c88fc786065218ccc200483f26de8013f1'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'El profesor como tal es muy buena nota y reconoce procedimiento en los exámenes algo fundamental si quiere pasar el curso a la primera. Es un poco desordenado con los apuntes por lo que es importante leer el libro antes de la clase. Ayuda banstante con las curvas y explica bien'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '5de0c2e7b36f2b45a310d1cb4ca85745847b2aa18201d812bef85bc36cb02686'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Califica duro pero se aprende mucho y hace la clase interesante'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '63c491e5f55c48ca3bf057b3636bae7d73804ae9cf94d8e3ae3424675cac54c2'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'La verdad es un profe que da bastante apoyo y muy buena nota. A uno lo ayuda en lo que necesite y se preocupa por que uno aprenda de verdad. Califica medio duro pero la verdad se aprende bastante con él. Muy comprensivo y la clase es muy interesante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-18T00:00:00+00:00'::TIMESTAMPTZ, '65a4c325c69f8cc34cde4f0fe1c607698880180fff21df3a8618e1e08fa1e02c'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Es exigente pero ayuda mucho en cuanto a sacar dudas o progresar con el trabajo. Muy buena retroalimentación en los informes y resultados. Se preocupa por que uno sea mejor estudiante y profesional.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'bb2da3bf30b29afffeae8983969f690ad3743daf3e67cadc54dc8d176abd827a'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Explica mas o menos bien pero se nota la desesperación por terminar la materia rapido, los apuntes son muy desordenados y cuando uno estudia cuesta mucho entenderlos.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'ae09e566b6298c67bd56d0d86d01ebd128ad29b17ba706c7428cb51c76d8fb9b'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Es bastante bueno, lo ayuda mucho a uno y le da explicaciones de lo que necesite. Califica duro los papers pero a favor de uno, no para perjudicarlo. Virtualmente se hace más sencillo y siempre está dispuesto a reunirse y a probar controles'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '25c6ead70557e7bf70742ca3f52eccf39a1d7aea4c5b7e070ed720b85b71c187'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Este profe no es tan bueno como dicen. Es como el aprendiz de chacón, pero la versión mala. Copia textual todo, póngale a estudiar. Siempre anda como en otras, entrega los exámenes suuuuuuper tarde. Uno al final no sabe ni qué obtuvo casi que al final del semestre.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'bcc71886b2a12a4adc8d3fce8156de533d9a74ff3c68a047cfcd19cd17f2be2b'::TEXT, ARRAY[1267]::BIGINT[]),
    (412::BIGINT, 'Yo no le entendía nada y veía las clases de Juan José, el profe es buena nota y le pone un montón, quiere que uno aprenda, pero en mi opinión es desordenado, califica de justo tirando a duro. No diría que es un mal profe pero tampoco considero que sea para cualquier tipo de estudiante.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'f7d75c0fc864f7f16ed8804418c122699d6b0f3e1c9a82804fb94fbf6ca31844'::TEXT, ARRAY[1267]::BIGINT[]),
    (412::BIGINT, 'Es un buen profesor, se nota que quiere educar a sus estudiantes. Lo único es que se nota cómo se deja influenciar por el profesor que coordina la cátedra. Es lamentable que alguien sin escrúpulos lo perjudique. Fuera de esto una excelente opción que brinda apoyo en la clase y fuera de ella.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'c583e5a4bb66e57e361aec1b44cd24811b2fa956f215dbdf579097c394fa8eea'::TEXT, ARRAY[1262]::BIGINT[]),
    (412::BIGINT, 'Es un profesor que pone mucho de su parte, sin embargo no es claro con lo que espera de las evaluaciones, no utiliza rúbricas califica a puro sentimiento. Por ejemplo, para él solo el mejor grupo puede obtener un 100 y los demás tienen que ir para abajo, a pesar de los demás cumplan las objetivos.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'ad5db036acf00c2a99b440adecb31469e68d16bd5514785ededb5d86f590e083'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Se ajustó bien a la modalidad virtual. Excelente persona y profesor, se preocupa porque uno entienda la materia. Le gusta mucho que participen en clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '021accfbbdd68717f5b085fa0c3c0ff1aa752f5ff5ffaebc534510fda274facb'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'El profe es excelente, de los mejores profesores que tiene la escuela, se preocupa por el estudiante y que aprenda del curso. Es una excelente opción'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-03T00:00:00+00:00'::TIMESTAMPTZ, '329e2ec8e72b3a378bc1bd564da1b6a071db7aba04affa75c21136a353c80cf7'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Buen profe pero hay que ponerle bastante, siempre esta a disposición de ayudar al estudiante siempre y cuando muestre interes en las clases'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'e7770aa5732fa096b3291eecbf379c8f998c82625749f57be28367955a37469b'::TEXT, ARRAY[1262, 1267]::BIGINT[]),
    (412::BIGINT, 'Un buen profesor. Puede llegar a confundirse en algún tema, pero intentará aclararse en la siguiente clase. Califica normal.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '7304a1f6ad0e0a224f68d76cb36e0eebdf8686ec7299463eba88cbedc105789d'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Fue la primera vez dando el curso, entonces el curso fue un poco más dificil para ser un lab. Deja demasiados trabajos y es confuso a veces. Él quiere que el estudiante pase bien, y te brinda ayuda cuando la ocupes. Siento que puede ser un profe muy bueno si da más este curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'e195e8db6dcaf237a271bd697f508fcbf5cb66acfdfb80f535708e83e76fdded'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'A veces se enreda un poco, sin embargo no es una mala opción para llevar el curso. Si estudia también del libro se entiende mucho mejor la clase'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'ac264cae988736fd0c287f11108b512b6662ca8e0c620f6a9ca18c3817c5c9df'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'El profe es muy bueno, CA es un curso muy pesado y con exámenes muy largos, el profe hace que el curso sea más llevadero y además se preocupa por el estudiante, si usted quiere las cosas regaladas en CA no lo va a lograr, estudien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '9ca855b3a7b2e4e882a31b7f67d92a90acec2b7ddb59cfc9c23a8b690e6b0dbf'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Un excelente profesor, explica muy bien. Si tiene dudas lo atiende en cualquier momento. Se preocupa porque uno entienda y aprenda. Califica suave y ayuda bastante. El curso es difícil y tiene demasiada materia, por lo que uno debe practicar mucho.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '10fb60044e53886d715b9f9c4f249f51faeb4e71767699f15641e27512af2314'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Es un profe amable, anuente a dudas y preocupado por el estudiante. Evalúa medianamente duro. Es MUY desordenado en la pizarra, a veces comete muchos errores al explicar la materia. Es importante ponerle desde el principio para pasar bien este curso.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6fbc06c21311e7ac6b345d2cb4b3d25fedcdad5cc435586f67ccd1c5362c285e'::TEXT, ARRAY[1267]::BIGINT[]),
    (412::BIGINT, 'Es un excelente Profe, tanto dando la materia, como calificando. Además en consulta saca el rato para explicarle mejor las cosas a uno y es muy buena persona, se preocupa porque el estudiante aprenda y es muy comprensivo. Lo recomiendo al 100%. El curso es obligatorio pero no siempre pasa lista.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, '95a7c520fc598b5705ef871f38de7149ab055a77d06b8cf6142430c6adf7415c'::TEXT, ARRAY[1267]::BIGINT[]),
    (412::BIGINT, 'Un excelente profesor, se preocupa por los alumnos y que quede clara la materia, en consulta se toma el tiempo necesario para que queden claras las cosas, solo le falta hacer un poco más de ejercicios con tiempo pero si se le dice él fijo los hace.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd2c5951ab5835296c330d5cc10f09cb085844a4a198bc22312346f927b0d28c2'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'En si el profe ayuda bastante y la mayoría de la materia queda clara, pero un problema es que básicamente todo lo copia de un cuaderno que él tiene, por lo que a ratos se olvida de explicar y nada más copia, pero no es mala opción.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2019-01-03T00:00:00+00:00'::TIMESTAMPTZ, '7a981c11835847acd91e7f2f539e60eb31c6cff2e93aa1b8eb265fea5989845f'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Sólo estudie del razavi, ez!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '06284e5777561fb2861328b981601d7d3a41d48775ef33fdbd212352d0e5abab'::TEXT, ARRAY[1267]::BIGINT[]),
    (412::BIGINT, 'No tiene manejo de la materia la mayoría del tiempo. El mae se esfuerza, pero más de una vez se queda en blanco cuando se le pregunta algo de la materia. Los exámenes están siendo bastantes más complicados que en semestres pasados y un profe así no ayuda. Lo recomiendo pero no para Activos.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '1a0390ceea514dd0af05dbb4452f9f09bdf21d1f55c281f0e15685abb1c8daca'::TEXT, ARRAY[1267]::BIGINT[]),
    (412::BIGINT, 'Este profe se nota que sabe, pero no lo que importa en este curso. El 65% de la materia que da no es relevante. Se la pasa sacando materia del "pedro julián" donde profundizan estúpidamente. Al final el exámen se hace con el Razavi. Hace ejercicios hasta el último día, cuando son el 80% del exámen.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-17T00:00:00+00:00'::TIMESTAMPTZ, '135408dc226ca58fbe1f2145fb152ae0956c6a717bf34585f5bade642c967777'::TEXT, ARRAY[1267]::BIGINT[]),
    (412::BIGINT, 'Excelente persona, siempre está dispuesto a ayudar, tanto en lab como en consulta y es muy accesible. Deja un proyecto duro pero da mucho tiempo y siempre ayuda. Para este lab es la mejor opción, sin duda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-12T00:00:00+00:00'::TIMESTAMPTZ, '19a35f4bef969496ad1764f8a9c89971062aced57019f0e8dcd17ffc3a66f9bb'::TEXT, ARRAY[3052]::BIGINT[]),
    (412::BIGINT, 'El profe muestra interés por los estudiantes pero le falta experiencia dando la materia y no se explica bien, probablemente en un par de semestres más sea excelente'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-31T00:00:00+00:00'::TIMESTAMPTZ, '6b191b44d81de6ed2434041a72b8ce4e9e3ff2c13d3d39ea7c629384a8d6f07f'::TEXT, ARRAY[1267]::BIGINT[]),
    (412::BIGINT, 'Excelente profesor y persona , califica lo normal las evaluaciones son acordes a lo que se ve en clase.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-30T00:00:00+00:00'::TIMESTAMPTZ, '04b89708974efdcf039c8cb212eec18eafd3414084fc6ada78bc769406b3ca40'::TEXT, ARRAY[3052]::BIGINT[]),
    (412::BIGINT, 'Un excelente profesor, explica y se sienta con usted a resolver los problemas que se le presenten y hasta puede que se quede hasta tarde trabajando con usted en el proyecto final. Simplemente un mae pura vida! Pone quices normales y es muy accesible.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1571d339432b0cfc082f10c0561b7bc9db29e02a4cf4551ba716a13874754f4e'::TEXT, ARRAY[3052]::BIGINT[]),
    (412::BIGINT, 'Se preocupa por el aprendizaje y toma en cuenta la dificultad del curso'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '47a0835cc08dd4e35c99b6ae7d845cf039791c5bd5e60f235c8503a4b40af757'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Un profesor con el que se puede dialogar y llegar a acuerdos. Su objetivo es que el estudiante aprenda. Se queda durante todo el laboratorio para ayudar algo que muchos otros profes no realizan. Sumamente pura vida. Evalúa de manera clara tal que se sepa que está mal. Quices normales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'e2f2eeac1b7e33a3ca5204cff1720006b7513a7437b4f759279d09e0d14574e5'::TEXT, ARRAY[3052]::BIGINT[]),
    (412::BIGINT, 'Excelente profesor. Se interesa porque la clase sea provechosa y explica muy bien. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '7c94e7a927f4b64c5bf3674488c011e23606fad94afb5b0f7c15cba85e704106'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Excelente profesor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'fd1a363b5968d7f3af01084a7369365eee5de24d4b6954550365cbe8767f912e'::TEXT, ARRAY[1321]::BIGINT[]),
    (412::BIGINT, 'Sin duda alguna uno de los mejores profesores de la escuela, recomendado al 100%'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-04-05T00:00:00+00:00'::TIMESTAMPTZ, 'dafa479d182b3a9c71ff0024a80fc99239725c7ac814468733acf41b1032d95b'::TEXT, ARRAY[3052]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
